import { useState } from 'react';
import { Box, Button, Typography, Alert, Dialog, DialogTitle, DialogContent, DialogActions, TextField } from '@mui/material';
import { useTracker } from '../tracker/TrackerProvider';
import { getTrackerDatabase, read } from '../tracker/storage';
import { Snapshot } from '../tracker/model';
import { reviewImport, backup, downloadBackup, parseBackup } from '../tracker/migration';
export function SyncSettings() {
    const { mode, setMode, user, client, snapshot, execute, busy, setError, supabaseUrl, supabaseKey, configureCloud } = useTracker();
    const [url, setUrl] = useState(supabaseUrl);
    const [key, setKey] = useState(supabaseKey);
    const [review, setReview] = useState<ReturnType<typeof reviewImport>>();
    const reviewLocal = async () => {
        try {
            if (!snapshot)
                return;
            const db = await getTrackerDatabase();
            const local = await read<Snapshot>(db, 'local:snapshot');
            const legacy = await read(db, 'legacy:backup');
            if (!local && !legacy)
                throw new Error('Open Local mode first to preserve and review this device’s data.');
            setReview(reviewImport(snapshot, local ?? parseBackup(legacy)));
        }
        catch (e) {
            setError((e as Error).message);
        }
    };
    return <Box sx={{ my: 2 }}><Typography variant="h6">Storage mode</Typography>
    <Typography>{mode === 'local' ? 'Local data stays on this device and works offline.' : 'Cloud changes require connectivity. Cached data stays readable offline.'}</Typography>
    {mode === 'local' && <details><summary>Cloud connection settings</summary><TextField label="Supabase URL" value={url} onChange={e => setUrl(e.target.value)}/><TextField label="Publishable key" value={key} onChange={e => setKey(e.target.value)}/><Button onClick={() => { try {
        configureCloud(url, key);
    }
    catch (e) {
        setError((e as Error).message);
    } }}>Save on this device</Button></details>}
    <Button disabled={busy} onClick={() => setMode(mode === 'local' ? 'cloud' : 'local')}>Use {mode === 'local' ? 'Cloud' : 'Local'}</Button>
    {mode === 'cloud' && <><Typography>{user?.email}</Typography><Button onClick={() => void (async () => { const result = await client?.auth.signOut(); if (result?.error)
        setError(result.error.message);
    else
        setMode('local'); })()}>Sign out</Button><Button onClick={() => void reviewLocal()}>Review local data for import</Button><Alert severity="info">Local data is independent. Review this device’s preserved data against the server before retiring an older installation.</Alert></>}
    <Dialog open={!!review} onClose={() => setReview(undefined)} fullWidth><DialogTitle>Review local import</DialogTitle><DialogContent><Typography>Identical records are skipped. The local source stays intact. Conflicting active sessions must be corrected explicitly before import.</Typography><pre style={{ whiteSpace: 'pre-wrap' }}>{review?.differences.join('\n') || 'All records are identical.'}</pre><Button onClick={() => snapshot && downloadBackup(backup(snapshot), 'before-import.json')}>Export current data</Button></DialogContent><DialogActions><Button onClick={() => setReview(undefined)}>Cancel</Button><Button disabled={busy || (!review?.mutations.length && review?.pausedProjectId === undefined)} onClick={() => void (async () => { try {
        await execute({ type: 'edit', intendedAt: new Date().toISOString(), pausedProjectId: review!.pausedProjectId, mutations: review!.mutations });
        setReview(undefined);
    }
    catch { /* provider displays failure; preserve review */ } })()}>Import reviewed records</Button></DialogActions></Dialog>
  </Box>;
}
