import React, { useState, useEffect } from 'react';
import {
  TextField,
  Button,
  Typography,
  Box,
  FormGroup,
  FormControlLabel,
  Checkbox,
  Divider,
  Chip,
  IconButton,
  Paper,
  Alert,
  Snackbar
} from '@mui/material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { de } from 'date-fns/locale/de';
import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Upload as UploadIcon,
  Download as DownloadIcon
} from '@mui/icons-material';
import { Settings } from '../types';
import { dateToYMD, parseYMDToDateLocal } from '../utils/timeUtils';
import { useTracker } from '../tracker/TrackerProvider';
import { backup, downloadBackup, parseBackup, reviewImport } from '../tracker/migration';
import { Dialog, DialogTitle, DialogContent, DialogActions } from '@mui/material';
import { SyncSettings } from './SyncSettings';

interface OvertimeAdjustment {
  id: string;
  date: string;
  hours: number;
  reason?: string;
}

interface SettingsPanelProps {
  settings: Settings;
  onSave: (settings: Settings) => void;
  overtimeAdjustments?: OvertimeAdjustment[];
  onAddAdjustment?: (adj: Omit<OvertimeAdjustment, 'id'>) => void;
  onDeleteAdjustment?: (id: string) => void;
  onClearDatabase?: () => void;
}

const WEEKDAYS = [
  { value: 0, label: 'Sunday' },
  { value: 1, label: 'Monday' },
  { value: 2, label: 'Tuesday' },
  { value: 3, label: 'Wednesday' },
  { value: 4, label: 'Thursday' },
  { value: 5, label: 'Friday' },
  { value: 6, label: 'Saturday' },
];

export const SettingsPanel: React.FC<SettingsPanelProps> = ({
  settings,
  onSave,
  overtimeAdjustments = [],
  onAddAdjustment,
  onDeleteAdjustment,
  onClearDatabase,
}) => {
  const { snapshot, execute, busy } = useTracker();
  const [importReview, setImportReview] = useState<ReturnType<typeof reviewImport>>();
  const [formData, setFormData] = useState<Settings>(settings);
  const [newVacationDate, setNewVacationDate] = useState<Date | null>(null);
  const [newAdjDate, setNewAdjDate] = useState<Date | null>(null);
  const [newAdjHours, setNewAdjHours] = useState<string>('');
  const [newAdjReason, setNewAdjReason] = useState<string>('');
  const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' | 'info' }>({
    open: false,
    message: '',
    severity: 'info'
  });

  useEffect(() => {
    // Preserve an open settings draft across remote refreshes.
  }, [settings]);

  const handleSave = async () => {
    try { await onSave(formData); } catch { return; }
    setFormData(current => ({...current,version:(current.version??0)+1}));
    setSnackbar({
      open: true,
      message: 'Settings saved successfully!',
      severity: 'success'
    });
  };

  const handleWorkdayChange = (day: number, checked: boolean) => {
    let newWorkdays: number[];
    if (checked) {
      newWorkdays = [...formData.workdays, day].sort((a, b) => a - b);
    } else {
      newWorkdays = formData.workdays.filter(d => d !== day);
    }
    setFormData(prev => ({ ...prev, workdays: newWorkdays }));
  };

  const handleAddVacationDay = () => {
    if (newVacationDate) {
  const dateString = dateToYMD(newVacationDate);
      if (!formData.vacationDays.includes(dateString)) {
        setFormData(prev => ({
          ...prev,
          vacationDays: [...prev.vacationDays, dateString].sort()
        }));
      }
      setNewVacationDate(null);
    }
  };

  const handleRemoveVacationDay = (dateString: string) => {
    setFormData(prev => ({
      ...prev,
      vacationDays: prev.vacationDays.filter(d => d !== dateString)
    }));
  };

  const [newOverrideMonth, setNewOverrideMonth] = useState<string>(() => {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
  });
  const [newOverrideHours, setNewOverrideHours] = useState<string>('0');

  const handleAddOverride = () => {
    if (!newOverrideMonth) return;
    const hours = parseFloat(newOverrideHours);
    if (isNaN(hours) || hours < 0) return;
    setFormData(prev => ({
      ...prev,
      paidOvertimeOverrides: {
        ...(prev.paidOvertimeOverrides || {}),
        [newOverrideMonth]: hours,
      },
    }));
  };

  const handleRemoveOverride = (month: string) => {
    setFormData(prev => {
      const nextOverrides = { ...(prev.paidOvertimeOverrides || {}) };
      delete nextOverrides[month];
      return {
        ...prev,
        paidOvertimeOverrides: nextOverrides,
      };
    });
  };

  const handleExportData = () => { if (snapshot) downloadBackup(backup(snapshot)); };
  const handleImportData = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file || !snapshot) return;
    try { setImportReview(reviewImport(snapshot, parseBackup(JSON.parse(await file.text())))); }
    catch (e) { setSnackbar({open:true, message:(e as Error).message, severity:'error'}); }
  };
  const applyImport = async () => {
    try { await execute({type:'edit', intendedAt:new Date().toISOString(), pausedProjectId:importReview!.pausedProjectId, mutations:importReview!.mutations}); setImportReview(undefined); }
    catch (e) { setSnackbar({open:true, message:(e as Error).message, severity:'error'}); }
  };

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={de}>
      <Box sx={{ p: 2 }}>
        <Button onClick={() => setFormData(settings)}>Reload settings (discard draft)</Button>
        <Typography variant="h5" gutterBottom>
          Settings
        </Typography>

        <Dialog open={!!importReview} onClose={() => setImportReview(undefined)} fullWidth>
          <DialogTitle>Review backup import</DialogTitle>
          <DialogContent><Typography>Identical records are skipped. Review replacements before applying. Credentials and pending commands are never imported.</Typography><pre style={{whiteSpace:'pre-wrap'}}>{importReview?.differences.join('\n') || 'All records are identical.'}</pre><details><summary>Compare values</summary><pre style={{whiteSpace:'pre-wrap'}}>{JSON.stringify(importReview?.mutations.map(m=>({entity:m.entity,id:m.id,current:snapshot?.records[m.entity][m.id]?.data,requested:m.data})),null,2)}</pre></details><Button onClick={handleExportData}>Export current data first</Button></DialogContent>
          <DialogActions><Button onClick={() => setImportReview(undefined)}>Cancel</Button><Button disabled={busy || (!importReview?.mutations.length && importReview?.pausedProjectId === undefined)} onClick={() => void applyImport()}>Import reviewed records</Button></DialogActions>
        </Dialog>
        <SyncSettings />

        <Box sx={{ py: 2 }}>
          <Typography variant="h6" gutterBottom>
            Work Schedule
          </Typography>

          <TextField
            label="Daily Target Hours"
            type="number"
            value={formData.dailyTargetHours}
            onChange={(e) => setFormData(prev => ({
              ...prev,
              dailyTargetHours: parseFloat(e.target.value) || 0
            }))}
            fullWidth
            margin="normal"
            inputProps={{ min: 0, max: 24, step: 0.5 }}
            helperText="Target working hours per day"
          />

          <TextField
            label="Initial Overtime Balance (hours)"
            type="number"
            value={formData.initialOvertimeHours ?? 0}
            onChange={(e) => setFormData(prev => ({
              ...prev,
              initialOvertimeHours: parseFloat(e.target.value) || 0
            }))}
            fullWidth
            margin="normal"
            inputProps={{ step: 0.5 }}
            helperText="Overtime carried over from before using the tracker. Positive = overtime, negative = undertime."
          />

          <TextField
            label="Paid Overtime per Month (hours)"
            type="number"
            value={formData.paidOvertimePerMonth ?? 0}
            onChange={(e) => setFormData(prev => ({
              ...prev,
              paidOvertimePerMonth: Math.max(0, parseFloat(e.target.value) || 0)
            }))}
            fullWidth
            margin="normal"
            inputProps={{ min: 0, step: 0.5 }}
            helperText="Monthly overtime hours compensated/paid with salary. These hours are not added to your overtime account."
          />

          <Box sx={{ mt: 2, mb: 1, p: 2, bgcolor: 'action.hover', borderRadius: 1 }}>
            <Typography variant="subtitle2" gutterBottom>
              Monthly Paid Overtime Overrides
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block" gutterBottom>
              Override the paid overtime allowance for specific months (e.g. 0h when the works council disallows it).
            </Typography>
            <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', mt: 1, flexWrap: 'wrap' }}>
              <TextField
                label="Month"
                type="month"
                size="small"
                value={newOverrideMonth}
                onChange={(e) => setNewOverrideMonth(e.target.value)}
                InputLabelProps={{ shrink: true }}
                sx={{ width: 170 }}
              />
              <TextField
                label="Paid Hours"
                type="number"
                size="small"
                value={newOverrideHours}
                onChange={(e) => setNewOverrideHours(e.target.value)}
                inputProps={{ min: 0, step: 0.5 }}
                sx={{ width: 120 }}
              />
              <Button
                variant="outlined"
                size="small"
                startIcon={<AddIcon />}
                onClick={handleAddOverride}
                disabled={!newOverrideMonth || isNaN(parseFloat(newOverrideHours)) || parseFloat(newOverrideHours) < 0}
              >
                Set Override
              </Button>
            </Box>

            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 2 }}>
              {Object.entries(formData.paidOvertimeOverrides || {})
                .sort(([a], [b]) => a.localeCompare(b))
                .map(([month, hours]) => (
                  <Chip
                    key={month}
                    label={`${month}: ${hours}h paid`}
                    onDelete={() => handleRemoveOverride(month)}
                    deleteIcon={<DeleteIcon />}
                    variant="outlined"
                    color={hours === 0 ? 'default' : 'primary'}
                  />
                ))}
              {Object.keys(formData.paidOvertimeOverrides || {}).length === 0 && (
                <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                  No monthly overrides set. All months use the default monthly value.
                </Typography>
              )}
            </Box>
          </Box>

          <Divider sx={{ my: 3 }} />

          <Typography variant="h6" gutterBottom>
            Time Tracking Start Date
          </Typography>
          <Typography variant="body2" color="text.secondary" gutterBottom>
            Set the date you started tracking time. This will adjust target calculations for the first month.
          </Typography>
          <DatePicker
            label="Tracking Start Date"
            value={parseYMDToDateLocal(formData.trackingStartDate)}
            onChange={(newValue) => {
              if (newValue) {
                setFormData(prev => ({ ...prev, trackingStartDate: dateToYMD(newValue) }));
              }
            }}
            slotProps={{ textField: { fullWidth: true, margin: 'normal' } }}
          />

          <Divider sx={{ my: 3 }} />

          <Typography variant="h6" gutterBottom>
            Working Days
          </Typography>
          <Typography variant="body2" color="text.secondary" gutterBottom>
            Select which days of the week you typically work
          </Typography>

          <FormGroup>
            {WEEKDAYS.map((day) => (
              <FormControlLabel
                key={day.value}
                control={
                  <Checkbox
                    checked={formData.workdays.includes(day.value)}
                    onChange={(e) => handleWorkdayChange(day.value, e.target.checked)}
                  />
                }
                label={day.label}
              />
            ))}
          </FormGroup>

          <Divider sx={{ my: 3 }} />

          <Typography variant="h6" gutterBottom>
            Vacation Days
          </Typography>
          <Typography variant="body2" color="text.secondary" gutterBottom>
            Add vacation days or days off. These will be excluded from target calculations.
          </Typography>

          <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-end', mb: 2 }}>
            <DatePicker
              label="Add Vacation Day"
              value={newVacationDate}
              onChange={(newValue) => setNewVacationDate(newValue)}
              slotProps={{ textField: { size: 'small', sx: { flex: 1 } } }}
            />
            <IconButton
              onClick={handleAddVacationDay}
              disabled={!newVacationDate}
              color="primary"
            >
              <AddIcon />
            </IconButton>
          </Box>

          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
            {formData.vacationDays.map((dateString) => (
              <Chip
                key={dateString}
                label={parseYMDToDateLocal(dateString).toLocaleDateString()}
                onDelete={() => handleRemoveVacationDay(dateString)}
                deleteIcon={<DeleteIcon />}
                variant="outlined"
              />
            ))}
            {formData.vacationDays.length === 0 && (
              <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                No vacation days added
              </Typography>
            )}
          </Box>

          {onAddAdjustment && onDeleteAdjustment && (
            <>
              <Divider sx={{ my: 3 }} />

              <Typography variant="h6" gutterBottom>
                Overtime Adjustments
              </Typography>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Add manual overtime corrections (e.g., work done off-tracker, comp time). These are added to the overtime total.
              </Typography>

              <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-end', mb: 2, flexWrap: 'wrap' }}>
                <DatePicker
                  label="Date"
                  value={newAdjDate}
                  onChange={(newValue) => setNewAdjDate(newValue)}
                  slotProps={{ textField: { size: 'small', sx: { minWidth: 150 } } }}
                />
                <TextField
                  label="Hours"
                  type="number"
                  value={newAdjHours}
                  onChange={(e) => setNewAdjHours(e.target.value)}
                  size="small"
                  inputProps={{ step: 0.5 }}
                  helperText="+/- hours"
                  sx={{ width: 120 }}
                />
                <TextField
                  label="Reason (optional)"
                  value={newAdjReason}
                  onChange={(e) => setNewAdjReason(e.target.value)}
                  size="small"
                  sx={{ flex: 1, minWidth: 150 }}
                />
                <IconButton
                  onClick={async () => {
                    if (newAdjDate && newAdjHours) {
                      try { await onAddAdjustment({
                        date: dateToYMD(newAdjDate),
                        hours: parseFloat(newAdjHours),
                        reason: newAdjReason || undefined,
                      }); } catch { return; }
                      setNewAdjDate(null);
                      setNewAdjHours('');
                      setNewAdjReason('');
                    }
                  }}
                  disabled={!newAdjDate || !newAdjHours || parseFloat(newAdjHours) === 0}
                  color="primary"
                >
                  <AddIcon />
                </IconButton>
              </Box>

              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                {overtimeAdjustments.map((adj) => (
                  <Chip
                    key={adj.id}
                    label={`${parseYMDToDateLocal(adj.date).toLocaleDateString()}: ${adj.hours > 0 ? '+' : ''}${adj.hours}h${adj.reason ? ` — ${adj.reason}` : ''}`}
                    onDelete={() => { void Promise.resolve(onDeleteAdjustment(adj.id)).catch(() => {}); }}
                    deleteIcon={<DeleteIcon />}
                    variant="outlined"
                    color={adj.hours >= 0 ? 'success' : 'error'}
                  />
                ))}
                {overtimeAdjustments.length === 0 && (
                  <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                    No overtime adjustments
                  </Typography>
                )}
              </Box>
            </>
          )}

          <Divider sx={{ my: 3 }} />

          <Typography variant="h6" gutterBottom>
            Data Management
          </Typography>
          <Typography variant="body2" color="text.secondary" gutterBottom>
            Export your data for backup or import from another device
          </Typography>

          <Paper sx={{ p: 2, mb: 3 }}>
            <Box sx={{ display: 'flex', gap: 2, flexDirection: { xs: 'column', sm: 'row' } }}>
              <Button
                variant="outlined"
                startIcon={<DownloadIcon />}
                onClick={handleExportData}
                sx={{ flex: 1 }}
              >
                Export All Data
              </Button>
              <Button
                variant="outlined"
                component="label"
                startIcon={<UploadIcon />}
                sx={{ flex: 1 }}
              >
                Import Data
                <input
                  type="file"
                  accept=".json"
                  onChange={handleImportData}
                  hidden
                />
              </Button>
            </Box>
            <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
              Use export/import to transfer data between devices or create backups
            </Typography>
          </Paper>

          {onClearDatabase && (
            <Paper sx={{ p: 2, mb: 3, border: '1px solid', borderColor: 'error.main' }}>
              <Typography variant="subtitle1" color="error" gutterBottom>
                Danger Zone
              </Typography>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Clear the selected dataset and restore defaults. Other accounts and the independent local dataset are unaffected. Export a backup first.
              </Typography>
              <Button
                variant="outlined"
                color="error"
                onClick={() => {
                  if (window.confirm('Are you sure you want to delete ALL data? This cannot be undone.')) {
                    void Promise.resolve(onClearDatabase()).catch(() => {});
                  }
                }}
              >
                Clear Database
              </Button>
            </Paper>
          )}

          <Box sx={{ mt: 3, p: 2, backgroundColor: 'action.hover', borderRadius: 1 }}>
            <Typography variant="body2" color="text.secondary">
              <strong>Note:</strong> These settings affect overtime calculations and progress tracking.
              Monthly targets are calculated automatically based on working days minus vacation days.
            </Typography>
          </Box>

          <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end' }}>
            <Button onClick={handleSave} variant="contained" size="large">
              Save Settings
            </Button>
          </Box>
        </Box>

        <Snackbar
          open={snackbar.open}
          autoHideDuration={3000}
          onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
        >
          <Alert
            onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
            severity={snackbar.severity}
          >
            {snackbar.message}
          </Alert>
        </Snackbar>
      </Box>
    </LocalizationProvider>
  );
};
